-- BidRush marketplace completion migration (run once against bidrush database)
ALTER TABLE tasks MODIFY status ENUM('draft','scheduled','live','awarded','in_progress','submitted','completed','cancelled','expired','disputed') NOT NULL DEFAULT 'draft';
ALTER TABLE tasks ADD COLUMN image_data MEDIUMBLOB NULL, ADD COLUMN image_mime VARCHAR(40) NULL, ADD COLUMN image_name VARCHAR(180) NULL;
CREATE TABLE IF NOT EXISTS task_extensions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,task_id CHAR(36) NOT NULL,actor_id CHAR(36) NOT NULL,minutes_added SMALLINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_extensions_task(task_id),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(160) NOT NULL,body VARCHAR(500) NOT NULL,href VARCHAR(255),is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_notifications_user_time(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS task_messages (id CHAR(36) PRIMARY KEY,task_id CHAR(36) NOT NULL,sender_id CHAR(36) NOT NULL,recipient_id CHAR(36) NOT NULL,body VARCHAR(2000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_messages_task_time(task_id,created_at),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(recipient_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS reports (id CHAR(36) PRIMARY KEY,task_id CHAR(36),reporter_id CHAR(36) NOT NULL,reason VARCHAR(80) NOT NULL,details VARCHAR(1500) NOT NULL,status ENUM('open','reviewing','resolved','dismissed') NOT NULL DEFAULT 'open',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_reports_status(status,created_at),FOREIGN KEY(reporter_id) REFERENCES users(id),FOREIGN KEY(task_id) REFERENCES tasks(id));
CREATE TABLE IF NOT EXISTS user_profiles (user_id CHAR(36) PRIMARY KEY,headline VARCHAR(120),bio VARCHAR(1500),skills JSON,location VARCHAR(100),updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_consents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id CHAR(36) NOT NULL,terms_version VARCHAR(30) NOT NULL,privacy_version VARCHAR(30) NOT NULL,accepted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,ip_hash CHAR(64),INDEX idx_consents_user(user_id),FOREIGN KEY(user_id) REFERENCES users(id));
